import{_ as d,o,c as l,a2 as a}from"./chunks/framework.BC3NdntU.js";const h=JSON.parse('{"title":"B2 构建工具对比","description":"","frontmatter":{},"headers":[],"relativePath":"附录B-对比清单/B2-构建工具对比.md","filePath":"附录B-对比清单/B2-构建工具对比.md","lastUpdated":1789034132000}'),e={name:"附录B-对比清单/B2-构建工具对比.md"};function r(s,t,i,n,u,c){return o(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="b2-构建工具对比" tabindex="-1">B2 构建工具对比 <a class="header-anchor" href="#b2-构建工具对比" aria-label="Permalink to &quot;B2 构建工具对比&quot;">​</a></h1><blockquote><p>附录 B · 对比清单</p></blockquote><h2 id="总对比表" tabindex="-1">总对比表 <a class="header-anchor" href="#总对比表" aria-label="Permalink to &quot;总对比表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>语言</th><th>定位</th><th>打包</th><th>树摇</th><th>生态</th><th>适用</th></tr></thead><tbody><tr><td>webpack</td><td>JS</td><td>应用打包元老</td><td>全量打包</td><td>强(需配置)</td><td><strong>最全</strong></td><td>存量复杂项目</td></tr><tr><td>Rollup</td><td>JS</td><td>库打包</td><td>库产物</td><td><strong>极致</strong></td><td>中</td><td>SDK/库</td></tr><tr><td>Vite</td><td>JS(esbuild+Rollup)</td><td>开发不打包</td><td>dev esbuild/build Rollup</td><td>强</td><td>成长中</td><td>新项目(默认)</td></tr><tr><td>esbuild</td><td>Go</td><td>转译/打包</td><td>极快</td><td>中</td><td>少</td><td>依赖预构建/提速</td></tr><tr><td>Rolldown</td><td>Rust</td><td>Rollup 的 Rust 重写</td><td>兼容 Rollup</td><td>强</td><td>成长中</td><td>Vite 未来内核</td></tr><tr><td>Rspack</td><td>Rust</td><td>webpack 的 Rust 重写</td><td>兼容 webpack</td><td>强</td><td>兼容 webpack</td><td>存量 webpack 提速</td></tr><tr><td>Turbopack</td><td>Rust</td><td>Next.js 增量打包</td><td>增量</td><td>强</td><td>Next 内置</td><td>Next.js</td></tr></tbody></table><hr><h2 id="关键差异" tabindex="-1">关键差异 <a class="header-anchor" href="#关键差异" aria-label="Permalink to &quot;关键差异&quot;">​</a></h2><ul><li><strong>webpack</strong>:先全量打包再启动,项目越大越慢;生态最全、兼容最强</li><li><strong>Vite</strong>:开发不打包(原生 ESM + 按需 esbuild),秒开;构建走 Rollup</li><li><strong>Rolldown/Rspack/Turbopack</strong>:用 Rust 重写,拿 esbuild 级速度 + 老生态兼容</li></ul><hr><h2 id="选型建议" tabindex="-1">选型建议 <a class="header-anchor" href="#选型建议" aria-label="Permalink to &quot;选型建议&quot;">​</a></h2><ul><li><strong>新项目</strong> → Vite(默认)</li><li><strong>打库/SDK</strong> → Rollup(或看 Rolldown 成熟度)</li><li><strong>存量 webpack 提速</strong> → Rspack(近零成本迁移)</li><li><strong>Next.js 重度</strong> → Turbopack(内置)</li><li><strong>Next.js 之外追求极致构建</strong> → 关注 Rolldown 进展</li></ul><blockquote><p><strong>应用 Vite、库 Rollup、存量提速 Rspack、未来看 Rolldown</strong>。</p></blockquote><hr><h2 id="深入思考" tabindex="-1">深入思考 <a class="header-anchor" href="#深入思考" aria-label="Permalink to &quot;深入思考&quot;">​</a></h2><ol><li><strong>为什么工具这么多</strong>:本质是&quot;性能&quot;与&quot;生态&quot;的拉锯——webpack 生态最全但慢,Vite 快但新,于是有了 Rust 重写(Rolldown/Rspack)想&quot;既要又要&quot;。</li><li><strong>迁移成本</strong>:从 webpack 迁 Vite/Rspack,真正的成本不在配置,而在&quot;非标准 loader/插件的适配&quot;。Rspack 靠兼容 webpack 协议把成本降到最低。</li><li><strong>未来</strong>:Rolldown 统一 Vite 双引擎后,&quot;开发/构建一致性&quot;问题会消失;构建工具最终会收敛到&quot;快 + 兼容&quot;的平衡点。</li></ol><hr><p>📎 参考:webpack/Vite/Rollup/Rolldown/Rspack/Turbopack 官方文档、卷五对应章节</p>',16)])])}const b=d(e,[["render",r]]);export{h as __pageData,b as default};
